css:
/* The painted poster: heroes in amber light, the blue blade, thin gold edges. */

.min-h-screen.surface-fond {
  background-image: linear-gradient(90deg, color-mix(in srgb, var(--surface-fond) 94%, transparent) 0%, color-mix(in srgb, var(--surface-fond) 80%, transparent) 45%, color-mix(in srgb, var(--surface-fond) 25%, transparent) 100%), var(--image-affiche);
  background-size: cover, auto 100vh;
  background-position: center, right top;
  background-repeat: no-repeat;
  background-attachment: fixed;
}
.surface-carte { background-color: color-mix(in srgb, var(--surface-carte) 84%, transparent); }
[data-app-menubar] { background-color: var(--surface-carte); }
.surface-carte.border, .rounded-2xl.border {
  border: 1px solid #f2a84a;
  box-shadow: inset 0 0 0 1px rgba(255, 226, 170, 0.12), 0 0 0 1px rgba(0, 0, 0, 0.55), 0 0 18px rgba(255, 170, 60, 0.18);
}
[data-app-menubar] { border-bottom: 1px solid #f2a84a; box-shadow: 0 1px 14px rgba(255, 170, 60, 0.2); }
.surface-menu {
  background-image: radial-gradient(ellipse 120% 50% at 50% 0%, color-mix(in srgb, var(--surface-menu) 85%, #ffffff) 0%, var(--surface-menu) 70%);
  border-right: 1px solid #f2a84a;
  box-shadow: 1px 0 16px rgba(255, 170, 60, 0.22);
}
[data-nav-title] { color: #ffb84f; text-transform: uppercase; letter-spacing: 0.22em; font-size: 10px; font-weight: 800; }
[aria-current="page"] { box-shadow: inset 0 0 0 1px #f2a84a, inset 0 0 14px rgba(255, 184, 79, 0.25); }
h1 { color: #e8962e; text-transform: uppercase; font-weight: 900; letter-spacing: 0.02em; text-shadow: 0 0 14px rgba(255, 170, 60, 0.45); }
[role="dialog"] { box-shadow: 0 0 0 1px #f2a84a, 0 0 32px rgba(255, 170, 60, 0.3); }
